#define PHI 1.61803398875  // The golden ratio
#define GOLDEN_ANGLE 2.399963229728653 // The golden angle in radians (~137.5 degrees)

// Hash function to generate random values
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    float tileSize = 150. / iResolution.y;
    vec2 hexUv = uv / tileSize;

    // Hexagonal grid coordinates
    float q = hexUv.x * (2.0 / 3.0);
    float r = (-hexUv.x / 3.0) + (sqrt(3.0) / 3.0) * hexUv.y;

    // Rounding to the nearest hex center
    float rq = round(q);
    float rr = round(r);
    float rs = round(-q - r);
    if (rq + rr + rs != 0.0) {
        float dq = abs(rq - q);
        float dr = abs(rr - r);
        float ds = abs(rs + q + r);
        if (dq > dr && dq > ds) {
            rq = -rr -rs;
        } else if (dr > ds) {
            rr = -rq -rs;
        }
    }

    // Local coordinates within the hexagon
    vec2 hexCenter = vec2(
        tileSize * (3.0 / 2.0) * rq,
        tileSize * sqrt(3.0) * (rr + 0.5 * rq)
    );
    vec2 tileUv = uv - hexCenter;

    // Determine time-based random rotation
    float timeStep = floor(iTime * 1.0);  // Every 0.5s a new rotation step
    float tileHash = hash(vec2(rq, rr) + timeStep); 
    float rotationStep = step(0.5, tileHash) * 1.0; // Randomly select tiles to rotate

    float rotationAngle = rotationStep * (3.14159265359 / 2.0); // Rotate 90 degrees
    float s = sin(rotationAngle), c = cos(rotationAngle);
    mat2 rotMatrix = mat2(c, -s, s, c);
    tileUv = rotMatrix * tileUv; // Rotate the UVs within the hexagonal tile

    // Random Truchet pattern selection
    float patternSelector = hash(vec2(rq, rr) + 1.);
              float k = patternSelector < .5 ? 12. : 12.5;
          float angle = atan(tileUv.y, tileUv.x);
         float radius = length(tileUv);
   float goldenSpiral = radius - pow(PHI, angle / GOLDEN_ANGLE);
        float pattern = smoothstep(.4, .416, fract(goldenSpiral * k));

    // Color the pattern
    vec3 baseColor = vec3(0.2, 0.2, 0.2);
    vec3 patternColor = vec3(1.0, 0.8, 0.2);
    vec3 color = mix(baseColor, patternColor, pattern);

    fragColor = vec4(color, 1.0);
}
